// Strategist pass: read dashboard data signals + the 'strategist' prompt, fill it, return
// one item { system, user } for the Anthropic call. All Supabase reads go through
// this.helpers.httpRequest so PostgREST arrays don't fan out into items. Scorecard reads
// are wrapped so a missing LP-MCP table degrades gracefully (master doc A5) rather than
// failing the run. Mark replaces __SUPABASE_URL__ / YOUR_SUPABASE_SERVICE_ROLE_KEY on import.
// TWO triggers: the fb-run-strategist webhook (dashboard button — explicit intent, may
// re-draft an existing brief) and the daily 7:00 AM ET schedule. Auto runs target the
// earliest upcoming planned slot without a brief and NEVER touch a slot whose brief is
// already draft/approved (return [] ends the run before the Anthropic call).
let body = {};
let isAuto = false;
try { body = $('Webhook (fb-run-strategist)').first().json.body || {}; } catch (e) { isAuto = true; }
const SB = '__SUPABASE_URL__';
const KEY = 'YOUR_SUPABASE_SERVICE_ROLE_KEY';
const h = { apikey: KEY, Authorization: 'Bearer ' + KEY };
const market = $env.SCORECARD_MARKET || 'REECE';
const safeGet = async (path) => { try { return await this.helpers.httpRequest({ method: 'GET', url: SB + path, headers: h, json: true }); } catch (e) { return []; } };

let scheduled_date = body.scheduled_date || '';
if (!scheduled_date) {
  if (isAuto) {
    const minDate = $now.plus({ days: 2 }).toFormat('yyyy-LL-dd');
    const nextSlot = await safeGet('/rest/v1/fb_content_plan?status=eq.planned&brief_status=eq.none&plan_date=gte.' + minDate + '&order=plan_date.asc&limit=1&select=plan_date');
    scheduled_date = (nextSlot && nextSlot[0] && nextSlot[0].plan_date) || $now.plus({ days: 3 }).toFormat('yyyy-LL-dd');
  } else {
    scheduled_date = $now.plus({ days: 3 }).toFormat('yyyy-LL-dd');
  }
}
const existRows = await safeGet('/rest/v1/fb_content_plan?plan_date=eq.' + scheduled_date + '&select=pillar,archetype,brief_status&limit=1');
const existing = (existRows && existRows[0]) || null;
if (isAuto && existing && existing.brief_status && existing.brief_status !== 'none') { return []; }

const prompts = await safeGet('/rest/v1/fb_messaging_prompts?is_active=eq.true&select=name,body');
const byName = Object.fromEntries((prompts || []).map(p => [p.name, p.body]));
const bankArr = await safeGet('/rest/v1/fb_message_bank?is_active=eq.true&select=variables&limit=1');
const bank = (bankArr && bankArr[0] && bankArr[0].variables) || {};
const subtopics = await safeGet('/rest/v1/fb_subtopics?status=eq.active&select=id,subtopic,pillar,last_used_at,times_used&order=last_used_at.asc.nullsfirst');
const recentPlan = await safeGet('/rest/v1/fb_content_plan?select=plan_date,pillar,archetype,subtopic_id&order=plan_date.desc&limit=60');
const engagement = await safeGet('/rest/v1/v_fb_post_engagement?select=pillar,archetype,engagement_rate');
const feedback = await safeGet('/rest/v1/fb_post_feedback?select=reason_code,component&order=created_at.desc&limit=500');
const srcRows = await safeGet('/rest/v1/lp_source_scorecard_daily?market=eq.' + market + '&order=as_of_date.desc&limit=40&select=source,sub_source,as_of_date,leads,demos,sales,close_pct,demo_pct,ko_pct,net_sales,nsli,avg_sale');
const mktRows = await safeGet('/rest/v1/lp_market_scorecard_daily?market=eq.' + market + '&order=as_of_date.desc&limit=1&select=as_of_date,leads,demos,sales,issued,net_sales,close_pct,demo_pct');
const goals = await safeGet('/rest/v1/scorecard_goals?market=eq.' + market + '&limit=1&select=monthly_goal_dollars,growth_pct,target_close_pct,target_demo_pct');

const latestSrcDate = (srcRows || []).reduce((a, r) => (r.as_of_date > a ? r.as_of_date : a), '');
const sources = (srcRows || []).filter(r => r.as_of_date === latestSrcDate).map(r => ({ source: r.source, sub_source: r.sub_source, leads: r.leads, demos: r.demos, sales: r.sales, close_pct: r.close_pct, demo_pct: r.demo_pct, ko_pct: r.ko_pct, net_sales: r.net_sales, nsli: r.nsli, avg_sale: r.avg_sale }));
const mkt = (mktRows && mktRows[0]) || null;
const goal = (goals && goals[0]) || null;

const objections = {};
(feedback || []).forEach(f => { objections[f.reason_code] = (objections[f.reason_code] || 0) + 1; });
const engByPillar = {};
(engagement || []).forEach(e => { if (e.engagement_rate == null) return; (engByPillar[e.pillar] = engByPillar[e.pillar] || []).push(Number(e.engagement_rate)); });
const recent_performance = Object.fromEntries(Object.entries(engByPillar).map(([k, v]) => [k, Math.round((v.reduce((a, b) => a + b, 0) / v.length) * 10000) / 10000]));

const d = new Date(scheduled_date + 'T00:00:00');
const monthName = d.toLocaleString('en-US', { month: 'long' });
const m = d.getMonth() + 1;
let season = monthName + '. ';
if (m >= 6 && m <= 11) season += 'FL hurricane season (Jun 1-Nov 30) — storm/insurance pillars weigh heavier.';
else if (m >= 5 && m <= 9) season += 'Peak FL heat — energy/comfort pillars resonate.';
else season += 'Off-peak — rotate pillars by recent performance.';

const dashboard_signals = {
  source_performance: sources,
  market_vs_goal: (mkt && goal) ? { net_sales: mkt.net_sales, monthly_goal_dollars: goal.monthly_goal_dollars, variance: (mkt.net_sales != null && goal.monthly_goal_dollars != null) ? (mkt.net_sales - goal.monthly_goal_dollars) : null, close_pct: mkt.close_pct, target_close_pct: goal.target_close_pct, demo_pct: mkt.demo_pct, target_demo_pct: goal.target_demo_pct } : (mkt || null),
  objection_signal: objections,
  note: (sources.length === 0 && !mkt) ? 'No scorecard data available — fall back to content performance + seasonal priority + least-recently-used rotation.' : undefined
};
const recently_used = { recent_plan: recentPlan || [], subtopics: (subtopics || []).slice(0, 40).map(s => ({ id: s.id, subtopic: s.subtopic, pillar: s.pillar, times_used: s.times_used })) };
const pillars = ['storm','noise','energy','security','comfort','insurance','uv','value'];

const user = (byName['strategist'] || '')
  .replaceAll('{{dashboard_signals}}', JSON.stringify(dashboard_signals))
  .replaceAll('{{recent_performance}}', JSON.stringify(recent_performance))
  .replaceAll('{{recently_used}}', JSON.stringify(recently_used))
  .replaceAll('{{season_context}}', season)
  .replaceAll('{{scheduled_date}}', scheduled_date)
  .replaceAll('{{pillar_list}}', pillars.join(', '))
  .replaceAll('{{message_bank}}', JSON.stringify(bank));

return [{ json: { system: byName['style_guide'] || '', user, scheduled_date, existing_pillar: existing ? existing.pillar : null, existing_archetype: existing ? existing.archetype : null } }];

// Tolerant JSON-object parse of the Content Brief, then build ONE upsert row for
// fb_content_plan. The brief merges onto the target date's slot (on_conflict=plan_date,
// merge-duplicates). pillar comes from the strategist's choice; archetype is preserved from
// an existing slot (or a safe default when creating a fresh slot, since archetype is NOT NULL).
// status is intentionally omitted so an existing slot keeps its status and a new row defaults
// to 'planned'. Human approves the brief in the dashboard before the producer consumes it.
let t = $json.content?.[0]?.text || '';
t = t.replace(/```json|```/g, '').trim();
let obj;
try { obj = JSON.parse(t); } catch (e) { const mm = t.match(/\{[\s\S]*\}/); obj = mm ? JSON.parse(mm[0]) : {}; }
if (Array.isArray(obj)) obj = obj[0] || {};
const b = $('Build Strategist Request').first().json;
const row = {
  plan_date: b.scheduled_date,
  pillar: obj.pillar || b.existing_pillar || 'value',
  archetype: b.existing_archetype || 'thought-leadership',
  brief: obj,
  brief_status: 'draft'
};
return [{ json: { rows: [row], scheduled_date: b.scheduled_date, pillar: row.pillar } }];
